CREATE TABLE users (id bigserial PRIMARY KEY, telegram_id bigint UNIQUE NOT NULL, name text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE admins (user_id bigint PRIMARY KEY REFERENCES users(id), role text NOT NULL CHECK(role IN ('owner','operator','viewer')));
CREATE TABLE locations (id bigserial PRIMARY KEY, name text UNIQUE NOT NULL, enabled boolean NOT NULL DEFAULT true);
CREATE TABLE servers (id bigserial PRIMARY KEY, location_id bigint NOT NULL REFERENCES locations(id), name text NOT NULL, api_url text NOT NULL, api_token text NOT NULL, capacity integer NOT NULL CHECK(capacity>0), status text NOT NULL DEFAULT 'enabled' CHECK(status IN ('enabled','disabled')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE services (id bigserial PRIMARY KEY, name text NOT NULL, description text NOT NULL DEFAULT '', enabled boolean NOT NULL DEFAULT true, trial_enabled boolean NOT NULL DEFAULT false);
CREATE TABLE plans (id bigserial PRIMARY KEY, service_id bigint NOT NULL REFERENCES services(id), name text NOT NULL, duration_hours integer NOT NULL CHECK(duration_hours>0), price_minor bigint NOT NULL CHECK(price_minor>=0), currency text NOT NULL DEFAULT 'IRR', enabled boolean NOT NULL DEFAULT true);
CREATE TABLE wallets (user_id bigint PRIMARY KEY REFERENCES users(id), balance_minor bigint NOT NULL DEFAULT 0 CHECK(balance_minor>=0));
CREATE TABLE wallet_transactions (id bigserial PRIMARY KEY, user_id bigint NOT NULL REFERENCES users(id), amount_minor bigint NOT NULL CHECK(amount_minor<>0), balance_after_minor bigint NOT NULL CHECK(balance_after_minor>=0), kind text NOT NULL CHECK(kind IN ('deposit','purchase','refund','adjustment')), reference text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX wallet_tx_user_time ON wallet_transactions(user_id,created_at DESC);
CREATE TABLE coupons (id bigserial PRIMARY KEY, code text UNIQUE NOT NULL, discount_percent integer NOT NULL CHECK(discount_percent BETWEEN 1 AND 100), max_uses integer NOT NULL CHECK(max_uses>0), uses integer NOT NULL DEFAULT 0, expires_at timestamptz);
CREATE TABLE orders (id bigserial PRIMARY KEY, user_id bigint NOT NULL REFERENCES users(id), plan_id bigint NOT NULL REFERENCES plans(id), server_id bigint NOT NULL REFERENCES servers(id), coupon_id bigint REFERENCES coupons(id), price_minor bigint NOT NULL CHECK(price_minor>=0), status text NOT NULL CHECK(status IN ('awaiting_payment','paid','provisioning','active','failed','refunded')), request_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,request_key));
CREATE INDEX orders_user_time ON orders(user_id,created_at DESC);
CREATE TABLE payments (id bigserial PRIMARY KEY, order_id bigint NOT NULL REFERENCES orders(id), provider text NOT NULL, provider_reference text UNIQUE, amount_minor bigint NOT NULL CHECK(amount_minor>=0), status text NOT NULL CHECK(status IN ('pending','confirmed','failed','refunded')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE subscriptions (id bigserial PRIMARY KEY, user_id bigint NOT NULL REFERENCES users(id), order_id bigint UNIQUE NOT NULL REFERENCES orders(id), server_id bigint NOT NULL REFERENCES servers(id), status text NOT NULL CHECK(status IN ('pending','active','expiring','expired','suspended','cancelled','provisioning_failed')), remote_id text, configuration text, expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX subscriptions_expiry ON subscriptions(expires_at) WHERE status IN ('active','expiring');
CREATE TABLE provisioning_jobs (id bigserial PRIMARY KEY, order_id bigint UNIQUE NOT NULL REFERENCES orders(id), subscription_id bigint UNIQUE NOT NULL REFERENCES subscriptions(id), server_id bigint NOT NULL REFERENCES servers(id), status text NOT NULL CHECK(status IN ('pending','processing','retrying','succeeded','failed')), attempts integer NOT NULL DEFAULT 0, run_after timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, last_error text, idempotency_key text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX jobs_queue ON provisioning_jobs(run_after) WHERE status IN ('pending','retrying','processing');
CREATE TABLE server_metrics (id bigserial PRIMARY KEY, server_id bigint NOT NULL REFERENCES servers(id), cpu_percent numeric, ram_percent numeric, swap_percent numeric, disk_percent numeric, uptime_seconds bigint, health text NOT NULL CHECK(health IN ('healthy','warning','critical','unavailable')), sampled_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX metrics_server_time ON server_metrics(server_id,sampled_at DESC);
CREATE TABLE alerts (id bigserial PRIMARY KEY, dedupe_key text NOT NULL, severity text NOT NULL CHECK(severity IN ('warning','critical')), title text NOT NULL, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','acknowledged','resolved')), opened_at timestamptz NOT NULL DEFAULT now(), acknowledged_at timestamptz, resolved_at timestamptz);
CREATE UNIQUE INDEX alert_open_key ON alerts(dedupe_key) WHERE status<>'resolved';
CREATE TABLE alert_events (id bigserial PRIMARY KEY, alert_id bigint NOT NULL REFERENCES alerts(id), action text NOT NULL, actor_id bigint REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE announcements (id bigserial PRIMARY KEY, title text NOT NULL, body text NOT NULL, published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications (id bigserial PRIMARY KEY, user_id bigint NOT NULL REFERENCES users(id), body text NOT NULL, delivered_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id bigserial PRIMARY KEY, actor_id bigint REFERENCES users(id), action text NOT NULL, entity text NOT NULL, entity_id bigint, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ai_messages (id bigserial PRIMARY KEY, user_id bigint NOT NULL REFERENCES users(id), role text NOT NULL CHECK(role IN ('user','assistant')), content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE trial_claims (user_id bigint NOT NULL REFERENCES users(id), service_id bigint NOT NULL REFERENCES services(id), PRIMARY KEY(user_id,service_id));
